const ctx = $('Input').first().json;
const userContent = 'Client: ' + ctx.client_name + '   Meeting: ' + (ctx.meeting_date ?? '') +
'\n\nEMAIL DIGEST: ' + JSON.stringify(ctx.email_digest ?? null) +
'\nLAST-MEETING RECAP: ' + JSON.stringify(ctx.recap ?? null) +
'\nBOOKS HEALTH: ' + JSON.stringify(ctx.books_health ?? null) +
'\nTAX ESTIMATE: ' + JSON.stringify(ctx.tax_estimate ?? null) +
'\nSTRATEGY SCREENER: ' + JSON.stringify(ctx.strategies ?? null) +
'\nSCORECARD: ' + JSON.stringify(ctx.scorecard ?? null) +
'\nKARBON OPEN ITEMS: ' + JSON.stringify(ctx.karbon_items ?? null) +
'\nFILE INVENTORY / PMT: ' + JSON.stringify(ctx.file_inventory ?? null) +
'\nCLIENT QUESTIONNAIRE: ' + JSON.stringify(ctx.questionnaire ?? null) +
'\nPREPARER NOTES (Karen): ' + JSON.stringify(ctx.preparer_notes ?? null);
const payload = {
  model: 'claude-opus-4-8',
  max_tokens: 16000,
  thinking: { type: 'adaptive' },
  system: "You are assembling the internal Meeting Brief a CPA will use to run a quarterly client meeting. You are given the outputs of every upstream step (email digest, last-meeting recap, books health, tax estimate, strategy screener, scorecard, Karbon items, questionnaire answers, and the preparer's own notes). Produce a single structured brief with the nine sections in the schema. Write for the preparer: concise, specific, decision-ready. Lead each section with what matters most. In \"Strategy Opportunities\", present the screener's candidates with their estimated savings and mark which need a Blue J memo \u2014 as options to evaluate, never as recommendations. Frame the financial review inside the tax story. Do not introduce facts that aren't in the inputs. Output only the JSON schema.",
  messages: [{ role: 'user', content: userContent }],
  output_config: { effort: 'high', format: { type: 'json_schema', schema: {"type": "object", "additionalProperties": false, "required": ["executive_summary", "since_last_meeting", "follow_up_items", "financial_review", "books_health", "tax_position", "strategy_opportunities", "key_talking_points", "questions_for_client"], "properties": {"executive_summary": {"type": "array", "items": {"type": "string"}}, "since_last_meeting": {"type": "string"}, "follow_up_items": {"type": "array", "items": {"type": "object", "additionalProperties": false, "required": ["item", "owner"], "properties": {"item": {"type": "string"}, "owner": {"type": "string"}}}}, "financial_review": {"type": "string"}, "books_health": {"type": "string"}, "tax_position": {"type": "string"}, "strategy_opportunities": {"type": "array", "items": {"type": "object", "additionalProperties": false, "required": ["strategy", "estimated_savings", "needs_memo"], "properties": {"strategy": {"type": "string"}, "estimated_savings": {"type": ["number", "null"]}, "needs_memo": {"type": "boolean"}}}}, "key_talking_points": {"type": "array", "items": {"type": "string"}}, "questions_for_client": {"type": "array", "items": {"type": "string"}}}} } }
};
return [{ json: { ...$json, payload } }];

// Structured outputs: the JSON arrives as a string in content[0].text.
const text = $json.content?.[0]?.text ?? '{}';
let out; try { out = JSON.parse(text); } catch (e) { out = { parse_error: true, raw: text }; }
const ctx = $('Input').first().json;
return [{ json: { ...ctx, brief: out } }];

const ctx = $json;
const b = ctx.brief ?? {};
const money = (n) => n == null ? 'TBD' : ('$' + Math.round(n).toLocaleString('en-US'));
const lines = [];
lines.push('MEETING BRIEF — ' + ctx.client_name + ' — ' + (ctx.meeting_date ?? ''));
lines.push('Internal preparation document. Draft for professional review — not client-facing.');
lines.push('');
lines.push('1. EXECUTIVE SUMMARY');
(b.executive_summary ?? []).forEach(s => lines.push('  • ' + s));
lines.push(''); lines.push('2. SINCE LAST MEETING'); lines.push(b.since_last_meeting ?? '');
lines.push(''); lines.push('3. FOLLOW-UP ITEMS');
(b.follow_up_items ?? []).forEach(f => lines.push('  • [' + f.owner + '] ' + f.item));
lines.push(''); lines.push('4. FINANCIAL REVIEW'); lines.push(b.financial_review ?? '');
lines.push(''); lines.push('5. BOOKS HEALTH'); lines.push(b.books_health ?? '');
lines.push(''); lines.push('6. TAX POSITION'); lines.push(b.tax_position ?? '');
lines.push(''); lines.push('7. STRATEGY OPPORTUNITIES (to evaluate — not recommendations)');
(b.strategy_opportunities ?? []).forEach(s => lines.push('  • ' + s.strategy + ' — est. ' + money(s.estimated_savings) + (s.needs_memo ? '  [needs Blue J memo + sign-off]' : '')));
lines.push(''); lines.push('8. KEY TALKING POINTS');
(b.key_talking_points ?? []).forEach((p, i) => lines.push('  ' + (i + 1) + '. ' + p));
lines.push(''); lines.push('9. QUESTIONS FOR THE CLIENT');
(b.questions_for_client ?? []).forEach(q => lines.push('  • ' + q));
return [{ json: { ...ctx, brief_text: lines.join('\n') } }];

const prev = $('Render brief text').first().json;
const docId = $('Create Brief Doc').first().json.id ?? $('Create Brief Doc').first().json.documentId;
return [{ json: { ...prev, brief_doc_id: docId, brief_doc_url: 'https://docs.google.com/document/d/' + docId + '/edit' } }];
